/* Main UI controller. Pages remain separate HTML files while sharing this readable application layer. */
const page = document.body.dataset.page;
const protectedPages = ['dashboard','tasks','courses','timetable','exams','notes','gpa','attendance','expenses','study-planner','profile','tools'];
const user = protectedPages.includes(page) ? requireAuth() : currentUser();
const navItems = [['dashboard.html','Dashboard','bi-grid-1x2'],['tasks.html','Tasks','bi-list-check'],['courses.html','Courses','bi-book'],['timetable.html','Timetable','bi-calendar3'],['exams.html','Exams','bi-mortarboard'],['notes.html','Notes','bi-sticky'],['gpa.html','GPA','bi-bar-chart'],['attendance.html','Attendance','bi-clipboard2-check'],['expenses.html','Expenses','bi-wallet2'],['study-planner.html','Study planner','bi-clock-history'],['resources.html','Resources','bi-collection'],['tools.html','Tools','bi-tools']];
function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char])); }
function formatShortDate(value) { return value ? new Date(`${value}T12:00`).toLocaleDateString([], { dateStyle: 'medium' }) : 'No date'; }
function formatDue(task) { const date = task.date || task.deadline; return `${date ? formatShortDate(date) : 'No date'}${task.time ? ` at ${escapeHtml(task.time)}` : ''}`; }
function emptyState(icon, title, message, action = '') { return `<div class="empty-state"><i class="bi ${icon}"></i><strong class="d-block text-dark">${title}</strong><span>${message}</span>${action ? `<div class="mt-3">${action}</div>` : ''}</div>`; }
function pageHeader(kicker, title, description, action = '') { return `<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">${kicker}</div><h1 class="display-title display-5 mb-2">${title}</h1><p class="text-secondary mb-0">${description}</p></div>${action}</div>`; }
function notificationPanel() { const data = getUserData() || defaultUserData(); const notifications = data.notifications || []; return `<div class="notification-panel d-none" id="notificationPanel"><div class="d-flex justify-content-between align-items-center mb-2"><strong>Notifications</strong><div class="d-flex gap-2"><button class="btn btn-sm btn-link text-secondary p-0" id="markAllRead">Mark all read</button><button class="btn btn-sm btn-link text-danger p-0" id="clearNotifications">Clear</button></div></div>${notifications.length ? notifications.slice(0,12).map(item => `<div class="notification-item ${item.read ? 'read' : ''}" data-notification-id="${item.id}"><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.message)}</p><small>${formatDateTime(item.createdAt)}</small></div>${item.read ? '' : '<button class="btn btn-sm btn-light mark-read" title="Mark as read"><i class="bi bi-check2"></i></button>'}</div>`).join('') : '<p class="small text-secondary mb-0">No notifications yet. Reminders and actual activity will appear here.</p>'}</div>`; }
function shell(content) { const active = `${page}.html`; const unread = (getUserData()?.notifications || []).filter(item => !item.read).length; const theme = getUserData()?.settings?.theme || 'light'; return `<div class="app-shell" data-theme="${theme}"><aside class="sidebar"><a class="brand d-block mb-4 px-2" href="index.html">Student<span class="brand-accent">Hub</span></a><p class="text-uppercase text-secondary small fw-bold px-2">Workspace</p><nav>${navItems.map(([href,label,icon]) => `<a class="nav-link ${href === active ? 'active' : ''}" href="${href}"><i class="bi ${icon} me-2"></i>${label}</a>`).join('')}</nav><div class="mt-auto pt-4"><button class="btn btn-sm btn-outline-secondary w-100" id="logoutButton"><i class="bi bi-box-arrow-right me-1"></i>Log out</button></div></aside><div class="main-content"><header class="topbar d-flex align-items-center justify-content-between px-3 px-lg-5"><div class="d-flex align-items-center gap-2"><span class="text-secondary small d-none d-md-inline">Workspace</span><span class="text-secondary d-none d-md-inline">›</span><strong class="text-capitalize">${escapeHtml(page.replaceAll('-', ' '))}</strong></div><div class="d-flex align-items-center gap-2 position-relative"><form id="globalSearchForm" class="global-search d-none d-md-flex"><i class="bi bi-search text-secondary"></i><input id="globalSearchInput" aria-label="Search your workspace" placeholder="Search tasks, notes, courses…"><kbd>⌘ K</kbd></form><button class="btn btn-sm btn-light border position-relative" id="notificationButton" title="Notifications" aria-label="Notifications"><i class="bi bi-bell"></i>${unread ? `<span class="notification-count">${unread}</span>` : ''}</button><button class="btn btn-sm btn-light border" id="themeButton" title="Toggle dark mode"><i class="bi ${theme === 'dark' ? 'bi-sun' : 'bi-moon'}"></i></button><a href="profile.html" class="btn btn-sm btn-light border rounded-circle" title="Profile">${escapeHtml((user?.name || 'S').slice(0,1).toUpperCase())}</a>${notificationPanel()}</div></header><main class="page-wrap">${content}</main><nav class="mobile-bottom">${navItems.slice(0,5).map(([href,label,icon]) => `<a class="${href === active ? 'active' : ''}" href="${href}"><i class="bi ${icon} d-block"></i>${label}</a>`).join('')}</nav></div></div>`; }
function bindShell() { document.getElementById('logoutButton')?.addEventListener('click', logoutUser); document.getElementById('themeButton')?.addEventListener('click', () => { updateUserData(data => ({ ...data, settings: { ...data.settings, theme: data.settings.theme === 'dark' ? 'light' : 'dark' } })); render(); }); const panel = document.getElementById('notificationPanel'); document.getElementById('notificationButton')?.addEventListener('click', () => panel?.classList.toggle('d-none')); document.getElementById('markAllRead')?.addEventListener('click', () => { updateUserData(data => ({ ...data, notifications: data.notifications.map(item => ({ ...item, read: true })) })); render(); }); document.getElementById('clearNotifications')?.addEventListener('click', () => { updateUserData(data => ({ ...data, notifications: [] })); render(); }); document.querySelectorAll('.mark-read').forEach(button => button.addEventListener('click', () => { const id = button.closest('.notification-item').dataset.notificationId; updateUserData(data => ({ ...data, notifications: data.notifications.map(item => item.id === id ? { ...item, read: true } : item) })); render(); })); document.getElementById('globalSearchForm')?.addEventListener('submit', event => { event.preventDefault(); const query = document.getElementById('globalSearchInput').value.trim(); if (query) window.location.href = `resources.html?search=${encodeURIComponent(query)}`; }); processUserNotifications(); }
function renderLanding() { document.getElementById('app').innerHTML = `<div class="landing-page"><nav class="navbar navbar-expand-lg py-4"><div class="container"><a class="brand fs-4" href="index.html">Student<span class="brand-accent">Hub</span></a><div class="d-flex gap-2"><a class="btn btn-outline-secondary btn-sm" href="login.html">Sign in</a><a class="btn btn-coral btn-sm" href="register.html">Create account</a></div></div></nav><section class="hero"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-6"><div class="eyebrow">A calmer way to stay on top of school</div><h1 class="mt-3">Make room for the work that <em>matters.</em></h1><p class="lead text-secondary mt-4">StudentHub brings deadlines, classes, exams, notes, and everyday student tasks into one focused workspace.</p><div class="d-flex gap-3 mt-4"><a class="btn btn-coral btn-lg" href="register.html">Get started <i class="bi bi-arrow-up-right"></i></a><a class="btn btn-link text-dark" href="#features">Explore features <i class="bi bi-arrow-right"></i></a></div></div><div class="col-lg-6"><div class="hero-preview card p-4"><div class="d-flex justify-content-between text-secondary small mb-4"><span>StudentHub / today</span><span>Plan with clarity</span></div><h2 class="display-title">Good morning.</h2><p class="text-secondary">Here’s what deserves your attention today.</p><div class="row g-3 mt-3"><div class="col-7"><div class="card p-3 bg-light"><small class="text-secondary">Today's focus</small><strong class="d-block mt-3">Your work, your rhythm</strong><div class="progress mt-4"><div class="progress-bar" style="width:63%;background:#789b82"></div></div></div></div><div class="col-5"><div class="card p-3 mb-3" style="background:#fff4f0"><small class="text-secondary">Reminders</small><strong class="d-block mt-2" style="color:#c85b45">Stay ahead</strong></div><div class="card p-3"><small class="text-secondary">Progress</small><strong class="d-block mt-2">Built from your data</strong></div></div></div></div></div></div></div></section><section id="features" class="py-5"><div class="container"><div class="eyebrow">One workspace, fewer loose ends</div><h2 class="display-title display-5 mt-2">Everything you need to find your <em>flow.</em></h2><div class="row g-3 mt-4">${[['bi-list-check','Tasks that move','Capture assignments, set deadlines, choose reminders, and keep momentum.'],['bi-calendar3','A week you can see','Build a timetable that makes room for classes and study.'],['bi-bell','Reminders with context','See active in-app reminders without pretending closed-browser alerts are guaranteed.'],['bi-sticky','Notes that stay close','Keep searchable course notes and PDFs in your own local workspace.']].map(([icon,title,text]) => `<div class="col-md-6 col-xl-3"><div class="feature-card card p-4"><i class="bi ${icon} fs-3 text-danger"></i><h3 class="h4 mt-4">${title}</h3><p class="text-secondary small">${text}</p></div></div>`).join('')}</div></div></section><footer class="container py-5 border-top"><div class="d-flex justify-content-between flex-wrap gap-3"><span class="brand">Student<span class="brand-accent">Hub</span></span><span class="small text-secondary">Editable HTML, CSS, JavaScript & Bootstrap source.</span></div></footer></div>`; }
function renderAuth(mode) {
  const register = mode === 'register';
  document.getElementById('app').innerHTML = `<main class="auth-page"><section class="auth-card card p-4 p-md-5"><a class="auth-brand fs-3" href="index.html">Student<span class="brand-accent">Hub</span></a><div class="eyebrow mt-4">${register ? 'Start with a clean slate' : 'Welcome back'}</div><h1 class="display-title h2 mt-2">${register ? 'Create your account' : 'Sign in to your workspace'}</h1><p class="text-secondary small">${register ? 'Your local prototype starts empty. Your account will remain available on this device after refresh, logout, and browser reopen.' : 'Use the account you created on this device.'}</p><div id="authAlert" aria-live="polite"></div><form id="authForm" class="mt-4" novalidate><div class="mb-3 ${register ? '' : 'd-none'}"><label class="form-label" for="name">Full name</label><div class="input-group"><span class="input-group-text"><i class="bi bi-person" aria-hidden="true"></i></span><input class="form-control" id="name" autocomplete="name" required></div></div><div class="mb-3"><label class="form-label" for="email">Email address</label><div class="input-group"><span class="input-group-text"><i class="bi bi-envelope" aria-hidden="true"></i></span><input class="form-control" id="email" type="email" autocomplete="email" required></div></div><div class="mb-3"><label class="form-label" for="password">Password</label><div class="input-group"><span class="input-group-text"><i class="bi bi-lock" aria-hidden="true"></i></span><input class="form-control" id="password" type="password" autocomplete="${register ? 'new-password' : 'current-password'}" minlength="8" required><button class="btn btn-light border" type="button" data-password-toggle="password" aria-label="Show password"><i class="bi bi-eye" aria-hidden="true"></i></button></div><div class="form-text">Minimum 8 characters.</div></div>${register ? '<div class="mb-3"><label class="form-label" for="confirmPassword">Confirm password</label><div class="input-group"><span class="input-group-text"><i class="bi bi-shield-check" aria-hidden="true"></i></span><input class="form-control" id="confirmPassword" type="password" autocomplete="new-password" minlength="8" required><button class="btn btn-light border" type="button" data-password-toggle="confirmPassword" aria-label="Show password"><i class="bi bi-eye" aria-hidden="true"></i></button></div></div>' : '<div class="form-check mb-3"><input class="form-check-input" id="remember" type="checkbox" checked><label class="form-check-label small" for="remember">Remember me on this device</label></div>'}<button class="btn btn-coral w-100" type="submit"><span class="button-label">${register ? 'Create account' : 'Sign in'}</span><span class="button-spinner spinner-border spinner-border-sm d-none" aria-hidden="true"></span></button></form><p class="text-center small text-secondary mt-4 mb-0">${register ? 'Already have an account?' : "Don't have an account?"} <a class="text-danger fw-bold" href="${register ? 'login.html' : 'register.html'}">${register ? 'Sign in' : 'Create one'}</a></p><p class="text-center small mt-3 mb-0"><a href="index.html" class="text-secondary">← Back to landing page</a></p></section></main>`;
  document.querySelectorAll('[data-password-toggle]').forEach(button => button.addEventListener('click', () => { const input = document.getElementById(button.dataset.passwordToggle); const visible = input.type === 'text'; input.type = visible ? 'password' : 'text'; button.setAttribute('aria-label', visible ? 'Show password' : 'Hide password'); button.innerHTML = `<i class="bi ${visible ? 'bi-eye' : 'bi-eye-slash'}" aria-hidden="true"></i>`; }));
  document.getElementById('authForm').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; const alertBox = document.getElementById('authAlert'); const submit = form.querySelector('button[type="submit"]'); submit.disabled = true; submit.querySelector('.button-label').classList.add('d-none'); submit.querySelector('.button-spinner').classList.remove('d-none'); alertBox.innerHTML = '<div class="alert alert-info small auth-status" role="status"><i class="bi bi-arrow-repeat spin me-1"></i> Working securely…</div>'; try { const email = document.getElementById('email').value; const password = document.getElementById('password').value; if (register) { if (password !== document.getElementById('confirmPassword').value) throw new Error('Passwords do not match.'); const created = await registerUser({ name: document.getElementById('name').value, email, password }); await loginUser(email, password); addActivity('account', 'You created your StudentHub account.'); alertBox.innerHTML = `<div class="alert alert-success small auth-status" role="status"><i class="bi bi-check-circle me-1"></i> Account created successfully. Welcome, ${escapeHtml(created.name.split(' ')[0])}.</div>`; window.setTimeout(() => { window.location.href = 'dashboard.html'; }, 700); } else { await loginUser(email, password, document.getElementById('remember').checked); alertBox.innerHTML = '<div class="alert alert-success small auth-status" role="status"><i class="bi bi-check-circle me-1"></i> Signed in successfully.</div>'; window.setTimeout(() => { window.location.href = 'dashboard.html'; }, 300); } } catch (error) { submit.disabled = false; submit.querySelector('.button-label').classList.remove('d-none'); submit.querySelector('.button-spinner').classList.add('d-none'); alertBox.innerHTML = `<div class="alert alert-danger small auth-status" role="alert"><i class="bi bi-exclamation-triangle me-1"></i> ${escapeHtml(error.message)}</div>`; } });
}
function taskStatus(task) { return task.status === 'completed' ? 'Completed' : taskIsOverdue(task) ? 'Overdue' : 'Pending'; }
function taskForm(task = {}) { const courses = getUserData().courses || []; return `<form id="taskForm" class="mt-3"><input type="hidden" id="taskId" value="${escapeHtml(task.id || '')}"><label class="form-label small" for="taskTitle">Task name *</label><input class="form-control mb-3" id="taskTitle" value="${escapeHtml(task.title || '')}" required><label class="form-label small" for="taskDescription">Description</label><textarea class="form-control mb-3" id="taskDescription" rows="3">${escapeHtml(task.description || '')}</textarea><div class="row g-2"><div class="col-7"><label class="form-label small" for="taskDate">Deadline/date</label><input class="form-control mb-3" id="taskDate" type="date" value="${escapeHtml(task.date || task.deadline || '')}"></div><div class="col-5"><label class="form-label small" for="taskTime">Time</label><input class="form-control mb-3" id="taskTime" type="time" value="${escapeHtml(task.time || '')}"></div></div><label class="form-label small" for="taskCourse">Course</label><select class="form-select mb-3" id="taskCourse"><option value="">No course</option>${courses.map(course => `<option value="${course.id}" ${course.id === task.courseId ? 'selected' : ''}>${escapeHtml(course.code ? `${course.code} — ${course.title}` : course.title)}</option>`).join('')}</select><label class="form-label small" for="taskPriority">Priority</label><select class="form-select mb-3" id="taskPriority"><option ${task.priority === 'Low' ? 'selected' : ''}>Low</option><option ${!task.priority || task.priority === 'Medium' ? 'selected' : ''}>Medium</option><option ${task.priority === 'High' ? 'selected' : ''}>High</option></select><label class="form-label small" for="taskReminder">Reminder</label><select class="form-select mb-3" id="taskReminder"><option value="">No reminder</option><option value="5m" ${task.reminder === '5m' ? 'selected' : ''}>5 minutes before</option><option value="15m" ${task.reminder === '15m' ? 'selected' : ''}>15 minutes before</option><option value="30m" ${task.reminder === '30m' ? 'selected' : ''}>30 minutes before</option><option value="1h" ${task.reminder === '1h' ? 'selected' : ''}>1 hour before</option><option value="1d" ${task.reminder === '1d' ? 'selected' : ''}>1 day before</option></select><div class="d-flex gap-2"><button class="btn btn-dark-green flex-grow-1">${task.id ? 'Save changes' : 'Add task'}</button>${task.id ? '<button class="btn btn-outline-secondary" type="button" id="cancelEdit">Cancel</button>' : ''}</div></form>`; }
function taskRows(tasks) { return tasks.length ? tasks.map(task => `<div class="border-top py-3 d-flex gap-3 align-items-start"><button class="btn btn-sm ${task.status === 'completed' ? 'btn-success' : 'btn-outline-secondary'} complete-task" data-id="${task.id}" title="${task.status === 'completed' ? 'Reopen task' : 'Mark complete'}"><i class="bi bi-check"></i></button><div class="flex-grow-1"><strong class="${task.status === 'completed' ? 'text-decoration-line-through text-secondary' : ''}">${escapeHtml(task.title)}</strong><div class="small text-secondary">${formatDue(task)} · ${escapeHtml(task.priority)} · ${escapeHtml(getCourseName(task.courseId))}</div>${task.description ? `<p class="small mb-0 mt-1 text-secondary">${escapeHtml(task.description)}</p>` : ''}<span class="badge ${taskStatus(task) === 'Overdue' ? 'text-bg-danger' : taskStatus(task) === 'Completed' ? 'badge-sage' : 'badge-soft'} mt-2">${taskStatus(task)}</span></div><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-secondary edit-task" data-id="${task.id}" title="Edit task"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-outline-danger delete-task" data-id="${task.id}" title="Delete task"><i class="bi bi-trash"></i></button></div></div>`).join('') : emptyState('bi-funnel', 'No tasks match', 'Create a task or change your filter to see more.'); }
function renderTasks() { const data = getUserData(); const activeFilter = new URLSearchParams(location.search).get('filter') || 'all'; let tasks = [...data.tasks]; if (activeFilter === 'completed') tasks = tasks.filter(task => task.status === 'completed'); if (activeFilter === 'overdue') tasks = tasks.filter(task => taskIsOverdue(task)); if (activeFilter === 'upcoming') tasks = tasks.filter(task => !taskIsOverdue(task) && task.status !== 'completed'); const editing = new URLSearchParams(location.search).get('edit'); const editingTask = data.tasks.find(task => task.id === editing); document.getElementById('app').innerHTML = shell(`${pageHeader('Plan → track', 'Tasks', 'Create, prioritize, edit, and complete every next step.', '<button class="btn btn-coral" id="requestNotifications"><i class="bi bi-bell me-1"></i>Enable browser alerts</button>')}<div class="row g-3"><div class="col-lg-4"><div class="card p-4"><h2 class="h5">${editingTask ? 'Edit task' : 'Add a task'}</h2>${taskForm(editingTask)}</div><div class="card p-4 mt-3"><h2 class="h6">Reminder behavior</h2><p class="small text-secondary mb-0">In-app reminders work while this app is open. Browser alerts depend on permission. Closed-browser delivery requires a future PWA or backend.</p></div></div><div class="col-lg-8"><div class="card p-4"><div class="d-flex flex-wrap justify-content-between gap-2"><div><h2 class="h5 mb-1">Your task list</h2><p class="small text-secondary mb-0">${data.tasks.length} total · ${data.tasks.filter(t => t.status === 'completed').length} complete</p></div><div class="btn-group btn-group-sm"><a class="btn btn-outline-secondary ${activeFilter === 'all' ? 'active' : ''}" href="tasks.html">All</a><a class="btn btn-outline-secondary ${activeFilter === 'upcoming' ? 'active' : ''}" href="tasks.html?filter=upcoming">Upcoming</a><a class="btn btn-outline-secondary ${activeFilter === 'completed' ? 'active' : ''}" href="tasks.html?filter=completed">Completed</a><a class="btn btn-outline-secondary ${activeFilter === 'overdue' ? 'active' : ''}" href="tasks.html?filter=overdue">Overdue</a></div></div><div id="taskList" class="mt-3">${taskRows(tasks)}</div></div></div></div>`); bindShell(); document.getElementById('requestNotifications')?.addEventListener('click', async () => { const result = await requestBrowserNotifications(); alert(result === 'granted' ? 'Browser notifications enabled.' : result === 'unsupported' ? 'This browser does not support notifications.' : 'Browser notifications remain disabled. In-app reminders still work.'); }); document.getElementById('taskForm').addEventListener('submit', event => { event.preventDefault(); const id = document.getElementById('taskId').value; const next = { id: id || makeId('task'), title: document.getElementById('taskTitle').value.trim(), description: document.getElementById('taskDescription').value.trim(), date: document.getElementById('taskDate').value, time: document.getElementById('taskTime').value, courseId: document.getElementById('taskCourse').value, priority: document.getElementById('taskPriority').value, reminder: document.getElementById('taskReminder').value, status: id ? (data.tasks.find(task => task.id === id)?.status || 'pending') : 'pending', createdAt: id ? (data.tasks.find(task => task.id === id)?.createdAt || new Date().toISOString()) : new Date().toISOString(), reminderDelivered: id ? Boolean(data.tasks.find(task => task.id === id)?.reminderDelivered) : false }; updateUserData(current => ({ ...current, tasks: id ? current.tasks.map(task => task.id === id ? next : task) : [...current.tasks, next] })); addActivity(id ? 'task-edit' : 'task-create', id ? `You edited ${next.title}` : `You created ${next.title}`); renderTasks(); }); document.getElementById('cancelEdit')?.addEventListener('click', () => { window.location.href = 'tasks.html'; }); document.querySelectorAll('.complete-task').forEach(button => button.addEventListener('click', () => { let changed; updateUserData(current => ({ ...current, tasks: current.tasks.map(task => { if (task.id !== button.dataset.id) return task; changed = { ...task, status: task.status === 'completed' ? 'pending' : 'completed' }; return changed; }) })); addActivity('task-status', changed.status === 'completed' ? `You completed ${changed.title}` : `You reopened ${changed.title}`); if (changed.status === 'completed') addNotification('task-completed', 'Task completed', changed.title, { taskId: changed.id }); renderTasks(); })); document.querySelectorAll('.edit-task').forEach(button => button.addEventListener('click', () => { window.location.href = `tasks.html?edit=${encodeURIComponent(button.dataset.id)}`; })); document.querySelectorAll('.delete-task').forEach(button => button.addEventListener('click', () => { const task = data.tasks.find(item => item.id === button.dataset.id); if (!task || !confirmDestructive('Delete task?', `Are you sure you want to delete “${task.title}”?`)) return; updateUserData(current => ({ ...current, tasks: current.tasks.filter(item => item.id !== task.id) })); addActivity('task-delete', `You deleted ${task.title}`); renderTasks(); })); }
function simpleListPage(type, title, kicker, description, fields, singular, renderItem) { const data = getUserData(); const items = data[type]; document.getElementById('app').innerHTML = shell(`${pageHeader(kicker, title, description)}<div class="row g-3"><div class="col-lg-4"><div class="card p-4"><h2 class="h5">Add ${singular}</h2><form id="simpleForm" class="mt-3">${fields.map(field => `<label class="form-label small" for="field-${field.key}">${field.label}</label><input class="form-control mb-3" id="field-${field.key}" ${field.type ? `type="${field.type}"` : ''} ${field.required ? 'required' : ''}>`).join('')}<button class="btn btn-dark-green w-100">Add ${singular}</button></form></div></div><div class="col-lg-8"><div class="card p-4"><div class="d-flex justify-content-between"><h2 class="h5">Your ${title.toLowerCase()}</h2><span class="small text-secondary">${items.length} total</span></div><div class="mt-3">${items.length ? items.map(renderItem).join('') : emptyState('bi-inbox','Nothing here yet',`Add your first ${singular} to start building your workspace.`)}</div></div></div></div>`); bindShell(); document.getElementById('simpleForm').addEventListener('submit', event => { event.preventDefault(); const item = { id: makeId(singular.replace(' ','-')), ...Object.fromEntries(fields.map(field => [field.key, document.getElementById(`field-${field.key}`).value])), createdAt: new Date().toISOString() }; updateUserData(current => ({ ...current, [type]: [...current[type], item] })); addActivity(`${singular}-create`, `You added ${item.title || singular}`); simpleListPage(type,title,kicker,description,fields,singular,renderItem); }); document.querySelectorAll('.delete-simple').forEach(button => button.addEventListener('click', () => { const item = items.find(entry => entry.id === button.dataset.id); if (!item || !confirmDestructive(`Delete ${singular}?`, `Are you sure you want to delete “${item.title || singular}”?`)) return; updateUserData(current => ({ ...current, [type]: current[type].filter(entry => entry.id !== item.id) })); simpleListPage(type,title,kicker,description,fields,singular,renderItem); })); }
function itemRow(item, singular, text) { return `<div class="border-top py-3 d-flex align-items-center gap-2"><div class="flex-grow-1">${text}</div><button class="btn btn-sm btn-outline-danger delete-simple" data-id="${item.id}" title="Delete ${singular}"><i class="bi bi-trash"></i></button></div>`; }
function renderDashboard() { const data = getUserData(); const now = new Date(); const today = now.toISOString().slice(0,10); const tasksToday = data.tasks.filter(task => (task.date || task.deadline) === today && task.status !== 'completed'); const upcoming = data.tasks.filter(task => !taskIsOverdue(task) && task.status !== 'completed').sort((a,b) => dateTimeValue(a.date || a.deadline,a.time)-dateTimeValue(b.date || b.deadline,b.time)).slice(0,5); const completed = data.tasks.filter(task => task.status === 'completed').length; const total = data.tasks.length; const unread = data.notifications.filter(item => !item.read).length; const activities = data.activities.slice(0,6); document.getElementById('app').innerHTML = shell(`${pageHeader('Your workspace', `Welcome to StudentHub, ${escapeHtml(user.name.split(' ')[0])}.`, 'Your real data, your next steps, and a calmer plan for today.')}<div class="quick-actions d-flex flex-wrap gap-2 mb-4"><a class="btn btn-coral" href="tasks.html"><i class="bi bi-plus"></i> Add task</a><a class="btn btn-outline-secondary" href="notes.html"><i class="bi bi-sticky"></i> Add note</a><a class="btn btn-outline-secondary" href="courses.html"><i class="bi bi-book"></i> Add course</a><a class="btn btn-outline-secondary" href="exams.html"><i class="bi bi-mortarboard"></i> Add exam</a><a class="btn btn-outline-secondary" href="study-planner.html"><i class="bi bi-play-circle"></i> Start study session</a><a class="btn btn-outline-secondary" href="expenses.html"><i class="bi bi-wallet2"></i> Add expense</a></div><div class="row g-3"><div class="col-lg-8"><div class="card p-4 h-100"><div class="d-flex justify-content-between"><div><h2 class="h5">Today’s focus</h2><p class="small text-secondary">${today}</p></div><span class="badge badge-soft">${tasksToday.length} due today</span></div>${tasksToday.length ? taskRows(tasksToday) : emptyState('bi-check2-square', 'Nothing due today', 'Create a task with a deadline to make today more actionable.', '<a class="btn btn-sm btn-soft" href="tasks.html">Create task</a>')}</div></div><div class="col-lg-4"><div class="card p-4 h-100" style="background:var(--ink);color:#fff"><div class="eyebrow" style="color:#f1b08f">Progress</div><h2 class="display-title h3 mt-3">Built from your data.</h2><div class="progress mt-4"><div class="progress-bar" style="width:${total ? Math.round(completed / total * 100) : 0}%;background:#e9a28d"></div></div><div class="d-flex justify-content-between small mt-2" style="color:#aab8b3"><span>${completed} completed</span><span>${total - completed} pending</span></div><p class="small mt-4 mb-0" style="color:#b9c8c2">${unread ? `${unread} unread notification${unread === 1 ? '' : 's'}.` : 'No unread notifications.'}</p></div></div><div class="col-md-6"><div class="card p-4"><div class="d-flex justify-content-between"><h2 class="h5">Upcoming</h2><a href="tasks.html?filter=upcoming" class="small text-danger">View all</a></div>${upcoming.length ? upcoming.map(task => `<div class="border-top py-3"><strong>${escapeHtml(task.title)}</strong><div class="small text-secondary">${formatDue(task)} · ${escapeHtml(taskStatus(task))}</div></div>`).join('') : emptyState('bi-calendar2-check','No upcoming deadlines','Your next deadlines will appear here.')}</div></div><div class="col-md-6"><div class="card p-4"><h2 class="h5">Recent activity</h2>${activities.length ? activities.map(activity => `<div class="border-top py-2 small"><strong>${escapeHtml(activity.message)}</strong><span class="d-block text-secondary">${formatDateTime(activity.createdAt)}</span></div>`).join('') : emptyState('bi-activity','No activity yet','Actions you take in your workspace will appear here.')}</div></div><div class="col-md-4"><div class="card stat-card"><div class="text-secondary small">Courses</div><div class="stat-value">${data.courses.length}</div><a href="courses.html" class="small text-danger">Add a course →</a></div></div><div class="col-md-4"><div class="card stat-card"><div class="text-secondary small">Exams</div><div class="stat-value">${data.exams.length}</div><a href="exams.html" class="small text-danger">Add an exam →</a></div></div><div class="col-md-4"><div class="card stat-card"><div class="text-secondary small">Study sessions</div><div class="stat-value">${data.studySessions.length}</div><a href="study-planner.html" class="small text-danger">Plan a session →</a></div></div></div>`); bindShell(); }
function renderNotes() { const data = getUserData(); const params = new URLSearchParams(location.search); const query = (params.get('search') || '').toLowerCase(); const courseFilter = params.get('course') || ''; const sort = params.get('sort') || 'newest'; let notes = data.notes.filter(note => (!query || `${note.title} ${note.body} ${getCourseName(note.courseId)}`.toLowerCase().includes(query)) && (!courseFilter || note.courseId === courseFilter)); notes.sort((a,b) => sort === 'oldest' ? new Date(a.createdAt) - new Date(b.createdAt) : sort === 'alpha' ? a.title.localeCompare(b.title) : sort === 'updated' ? new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt) : new Date(b.createdAt) - new Date(a.createdAt)); const selected = notes[0] || data.notes[0]; document.getElementById('app').innerHTML = shell(`${pageHeader('Capture → connect','Notes','Create, search, filter, edit, and safely manage your notes.','<button class="btn btn-coral" id="newNote"><i class="bi bi-plus"></i> New note</button>')}<div class="card p-4"><div class="row g-4"><div class="col-lg-4"><div class="d-flex gap-2 mb-2"><input class="form-control form-control-sm" id="noteSearch" placeholder="Search title, course, content" value="${escapeHtml(params.get('search') || '')}"><button class="btn btn-sm btn-outline-secondary" id="applyNoteSearch"><i class="bi bi-search"></i></button></div><div class="d-flex gap-2 mb-3"><select class="form-select form-select-sm" id="noteCourseFilter"><option value="">All courses</option>${data.courses.map(course => `<option value="${course.id}" ${course.id === courseFilter ? 'selected' : ''}>${escapeHtml(course.title)}</option>`).join('')}</select><select class="form-select form-select-sm" id="noteSort"><option value="newest" ${sort==='newest'?'selected':''}>Newest</option><option value="oldest" ${sort==='oldest'?'selected':''}>Oldest</option><option value="updated" ${sort==='updated'?'selected':''}>Updated</option><option value="alpha" ${sort==='alpha'?'selected':''}>A–Z</option></select></div><div class="note-list">${notes.length ? notes.map(note => `<div class="note-list-item ${selected?.id === note.id ? 'active' : ''}" data-id="${note.id}"><div class="d-flex justify-content-between gap-2"><button class="btn btn-link p-0 text-start note-open" data-id="${note.id}"><strong>${escapeHtml(note.title)}</strong></button><button class="btn btn-sm btn-link text-danger p-0 delete-note" data-id="${note.id}" title="Delete note"><i class="bi bi-trash"></i></button></div><span>${escapeHtml(getCourseName(note.courseId))}</span><p>${escapeHtml((note.body || '').slice(0,80))}</p></div>`).join('') : emptyState('bi-sticky','No matching notes','Create a note or change your search.')}</div><hr><h3 class="h6">Related PDFs</h3><div id="pdfList">${renderPdfList(data.pdfs || [], data.courses)}</div><form id="pdfForm" class="mt-3"><label class="form-label small" for="pdfTitle">PDF title</label><input class="form-control form-control-sm mb-2" id="pdfTitle" required><label class="form-label small" for="pdfCourse">Course</label><select class="form-select form-select-sm mb-2" id="pdfCourse"><option value="">No course</option>${data.courses.map(course => `<option value="${course.id}">${escapeHtml(course.title)}</option>`).join('')}</select><input class="form-control form-control-sm mb-2" id="pdfFile" type="file" accept="application/pdf,.pdf" required><button class="btn btn-sm btn-outline-secondary">Save PDF</button><div class="form-text">Local prototype limit: 2 MB per PDF.</div></form></div><div class="col-lg-8"><div id="noteEditor">${selected ? noteEditor(selected, data.courses) : emptyState('bi-pencil-square','Select a note','Create your first note to begin writing.')}</div></div></div></div>`); bindShell(); document.getElementById('newNote')?.addEventListener('click', () => { const note = { id: makeId('note'), title: 'Untitled note', courseId: '', body: '', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; updateUserData(current => ({ ...current, notes: [note, ...current.notes] })); addActivity('note-create', 'You created a new note'); renderNotes(); }); document.getElementById('applyNoteSearch')?.addEventListener('click', () => { const search = document.getElementById('noteSearch').value; const course = document.getElementById('noteCourseFilter').value; const selectedSort = document.getElementById('noteSort').value; window.location.href = `notes.html?search=${encodeURIComponent(search)}&course=${encodeURIComponent(course)}&sort=${selectedSort}`; }); document.getElementById('noteCourseFilter')?.addEventListener('change', () => document.getElementById('applyNoteSearch').click()); document.getElementById('noteSort')?.addEventListener('change', () => document.getElementById('applyNoteSearch').click()); document.querySelectorAll('.note-open').forEach(button => button.addEventListener('click', () => { const note = data.notes.find(item => item.id === button.dataset.id); const currentBody = document.getElementById('noteBody')?.value || ''; const original = document.getElementById('noteOriginal')?.value || ''; if (currentBody !== original && !window.confirm('You have unsaved changes. Leave without saving?')) return; document.getElementById('noteEditor').innerHTML = noteEditor(note, data.courses); bindNoteEditor(); })); document.querySelectorAll('.delete-note').forEach(button => button.addEventListener('click', () => { const note = data.notes.find(item => item.id === button.dataset.id); if (!note || !confirmDestructive('Delete note?', `Are you sure you want to delete “${note.title}”?`)) return; updateUserData(current => ({ ...current, notes: current.notes.filter(item => item.id !== note.id) })); addActivity('note-delete', `You deleted ${note.title}`); renderNotes(); })); bindNoteEditor(); document.getElementById('pdfForm')?.addEventListener('submit', handlePdfUpload); document.querySelectorAll('.delete-pdf').forEach(button => button.addEventListener('click', () => deletePdf(button.dataset.id))); }
function noteEditor(note, courses) { return `<form id="noteForm"><input type="hidden" id="noteId" value="${note.id}"><input type="hidden" id="noteOriginal" value="${escapeHtml(note.body || '')}"><label class="visually-hidden" for="noteTitle">Note title</label><input class="form-control form-control-lg mb-3" id="noteTitle" value="${escapeHtml(note.title)}" required><label class="form-label small" for="noteCourse">Course</label><select class="form-select mb-3" id="noteCourse"><option value="">General</option>${courses.map(course => `<option value="${course.id}" ${course.id === note.courseId ? 'selected' : ''}>${escapeHtml(course.title)}</option>`).join('')}</select><label class="form-label small" for="noteBody">Content</label><textarea class="form-control" id="noteBody" rows="18">${escapeHtml(note.body || '')}</textarea><div class="d-flex justify-content-between align-items-center mt-3"><small class="text-secondary">Created ${formatDateTime(note.createdAt)} · Updated ${formatDateTime(note.updatedAt)}</small><button class="btn btn-dark-green">Save note</button></div></form>`; }
function bindNoteEditor() { const form = document.getElementById('noteForm'); if (!form) return; form.addEventListener('submit', event => { event.preventDefault(); const id = document.getElementById('noteId').value; const next = { title: document.getElementById('noteTitle').value.trim(), courseId: document.getElementById('noteCourse').value, body: document.getElementById('noteBody').value, updatedAt: new Date().toISOString() }; updateUserData(data => ({ ...data, notes: data.notes.map(note => note.id === id ? { ...note, ...next } : note) })); addActivity('note-edit', `You updated ${next.title}`); renderNotes(); }); }
function renderPdfList(pdfs, courses) { return pdfs.length ? pdfs.map(pdf => `<div class="border-top py-2 small"><strong>${escapeHtml(pdf.title)}</strong><span class="d-block text-secondary">${escapeHtml(pdf.filename)} · ${Math.round(pdf.size / 1024)} KB · ${escapeHtml(getCourseName(pdf.courseId, { courses }))}</span><div class="d-flex gap-2 mt-1"><a class="btn btn-sm btn-outline-secondary" href="${pdf.dataUrl}" target="_blank" rel="noopener">Open PDF</a><button class="btn btn-sm btn-outline-danger delete-pdf" data-id="${pdf.id}">Delete</button></div></div>`).join('') : '<p class="small text-secondary">No PDFs saved yet.</p>'; }
function handlePdfUpload(event) { event.preventDefault(); const file = document.getElementById('pdfFile').files[0]; if (!file) return; if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) { alert('Please choose a PDF file.'); return; } if (file.size > 2 * 1024 * 1024) { alert('This prototype accepts PDFs up to 2 MB. Larger files should be moved to proper file storage.'); return; } const reader = new FileReader(); reader.onload = () => { const pdf = { id: makeId('pdf'), title: document.getElementById('pdfTitle').value.trim(), courseId: document.getElementById('pdfCourse').value, filename: file.name, size: file.size, dataUrl: reader.result, uploadedAt: new Date().toISOString() }; updateUserData(data => ({ ...data, pdfs: [pdf, ...(data.pdfs || [])] })); addActivity('pdf-upload', `You added ${pdf.title}`); renderNotes(); }; reader.readAsDataURL(file); }
function deletePdf(id) { const pdf = getUserData().pdfs.find(item => item.id === id); if (!pdf || !confirmDestructive('Delete PDF?', `Are you sure you want to delete “${pdf.title}”?`)) return; updateUserData(data => ({ ...data, pdfs: data.pdfs.filter(item => item.id !== id) })); addActivity('pdf-delete', `You deleted ${pdf.title}`); renderNotes(); }
function renderProfile() { document.getElementById('app').innerHTML = shell(`${pageHeader('Your account','Profile','Manage the local profile used by this browser.')}<div class="card p-4" style="max-width:700px"><div class="alert alert-warning small"><i class="bi bi-info-circle me-1"></i>This downloadable prototype stores accounts and student data in browser storage. It is not a production authentication service.</div><form id="profileForm"><label class="form-label small" for="profileName">Full name</label><input class="form-control mb-3" id="profileName" value="${escapeHtml(user.name)}" required><label class="form-label small" for="profileEmail">Email address</label><input class="form-control mb-3" id="profileEmail" value="${escapeHtml(user.email)}" type="email" required><label class="form-label small">Account created</label><p class="text-secondary small">${new Date(user.createdAt).toLocaleString()}</p><button class="btn btn-dark-green">Save profile</button></form></div>`); bindShell(); document.getElementById('profileForm').addEventListener('submit', event => { event.preventDefault(); const name = document.getElementById('profileName').value.trim(); const email = document.getElementById('profileEmail').value.trim().toLowerCase(); const duplicate = getUsers().some(item => item.id !== user.id && item.email === email); if (!name || !/^\S+@\S+\.\S+$/.test(email)) return alert('Enter a valid name and email.'); if (duplicate) return alert('That email is already used by another account.'); saveUsers(getUsers().map(item => item.id === user.id ? { ...item, name, email } : item)); addActivity('profile', 'You updated your profile.'); alert('Profile saved on this device.'); }); }
function renderTools() { document.getElementById('app').innerHTML = shell(`${pageHeader('Small tools, right when you need them','Tools','Quick, focused utilities for the moments between classes and deadlines.')}<div class="row g-3"><div class="col-md-6 col-xl-4"><div class="card p-4"><h2 class="h5">Word counter</h2><textarea class="form-control mt-3" id="wordText" rows="7" placeholder="Paste or write here..."></textarea><div class="d-flex gap-4 mt-3 small text-secondary"><span>Words <strong id="wordCount" class="d-block text-dark fs-5">0</strong></span><span>Characters <strong id="charCount" class="d-block text-dark fs-5">0</strong></span></div></div></div><div class="col-md-6 col-xl-4"><div class="card p-4"><h2 class="h5">Percentage calculator</h2><div class="input-group mt-3"><input class="form-control" id="percentA" type="number" placeholder="20"><span class="input-group-text">% of</span><input class="form-control" id="percentB" type="number" placeholder="50"></div><div class="bg-light rounded p-3 mt-3" id="percentResult">Enter two numbers.</div></div></div><div class="col-md-6 col-xl-4"><div class="card p-4"><h2 class="h5">Pomodoro timer</h2><div class="display-title display-4 text-center my-4" id="timerDisplay">25:00</div><div class="d-flex justify-content-center gap-2"><button class="btn btn-coral" id="startTimer">Start</button><button class="btn btn-outline-secondary" id="resetTimer">Reset</button></div></div></div></div>`); bindShell(); let timer=1500, interval=null; const display=()=>document.getElementById('timerDisplay').textContent=`${String(Math.floor(timer/60)).padStart(2,'0')}:${String(timer%60).padStart(2,'0')}`; document.getElementById('wordText').addEventListener('input',event=>{const text=event.target.value;document.getElementById('wordCount').textContent=countWords(text);document.getElementById('charCount').textContent=text.length;}); ['percentA','percentB'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{const a=Number(document.getElementById('percentA').value),b=Number(document.getElementById('percentB').value);document.getElementById('percentResult').textContent=(a&&b)?`${(a/100*b).toFixed(2)}`:'Enter two numbers.';})); document.getElementById('startTimer').addEventListener('click',()=>{if(interval)return;interval=setInterval(()=>{timer=Math.max(0,timer-1);display();if(!timer){clearInterval(interval);interval=null;addActivity('study', 'You completed a study timer.');}},1000);});document.getElementById('resetTimer').addEventListener('click',()=>{clearInterval(interval);interval=null;timer=1500;display();}); }
function simplePageFor(type) { const map = { courses: ['Courses','Build your semester','Set up the subjects connected to your work.', [{key:'code',label:'Course code',required:true},{key:'title',label:'Course title',required:true},{key:'lecturer',label:'Lecturer'}], 'course', item => itemRow(item,'course',`<strong>${escapeHtml(item.code)} — ${escapeHtml(item.title)}</strong><div class="small text-secondary">${escapeHtml(item.lecturer || 'Lecturer not added')}</div>`)], exams: ['Exams','Keep important dates visible','Add upcoming exams and keep the countdown in view.', [{key:'title',label:'Exam title',required:true},{key:'date',label:'Date',type:'date',required:true},{key:'location',label:'Location'}], 'exam', item => itemRow(item,'exam',`<strong>${escapeHtml(item.title)}</strong><div class="small text-secondary">${escapeHtml(item.date)} · ${escapeHtml(item.location || 'Location not added')}</div>`)], timetable: ['Timetable','Shape the week','Add classes and study blocks to give the week structure.', [{key:'title',label:'Class or study block',required:true},{key:'day',label:'Day',required:true},{key:'time',label:'Time'}], 'class', item => itemRow(item,'class',`<strong>${escapeHtml(item.title)}</strong><div class="small text-secondary">${escapeHtml(item.day)} · ${escapeHtml(item.time || 'Time not added')}</div>`)] }; const config = map[type]; simpleListPage(type, config[0], 'Build → review', config[2], config[3], config[4], config[5]); }
function renderResources() { const query = new URLSearchParams(location.search).get('search') || ''; const data = getUserData() || defaultUserData(); const results = []; data.tasks.forEach(item => results.push({ type:'Task', title:item.title, text:item.description || formatDue(item), href:'tasks.html' })); data.notes.forEach(item => results.push({ type:'Note', title:item.title, text:item.body || getCourseName(item.courseId), href:'notes.html' })); data.courses.forEach(item => results.push({ type:'Course', title:item.title, text:item.code || '', href:'courses.html' })); data.exams.forEach(item => results.push({ type:'Exam', title:item.title, text:item.date || '', href:'exams.html' })); const filtered = results.filter(item => !query || `${item.type} ${item.title} ${item.text}`.toLowerCase().includes(query.toLowerCase())); document.getElementById('app').innerHTML = shell(`${pageHeader('Find → focus','Search','Search actual tasks, notes, courses, and exams.')}<div class="card p-4"><form id="resourceSearch" class="d-flex gap-2 mb-4"><input class="form-control" id="searchInput" value="${escapeHtml(query)}" placeholder="Search your workspace" aria-label="Search your workspace"><button class="btn btn-coral">Search</button></form>${query && !filtered.length ? emptyState('bi-search','No results found','Try a different title, course, or keyword.') : filtered.length ? filtered.map(item => `<a href="${item.href}" class="search-result border-top py-3 d-flex gap-3"><i class="bi bi-${item.type === 'Task' ? 'check2-square' : item.type === 'Note' ? 'sticky' : item.type === 'Course' ? 'book' : 'mortarboard'} fs-4 text-danger"></i><span><strong>${escapeHtml(item.title)}</strong><small class="d-block text-secondary">${escapeHtml(item.type)} · ${escapeHtml(item.text)}</small></span><i class="bi bi-arrow-up-right ms-auto"></i></a>`).join('') : emptyState('bi-search','Search your workspace','Your actual records will appear here as you create them.')}</div>`); bindShell(); document.getElementById('resourceSearch').addEventListener('submit', event => { event.preventDefault(); window.location.href = `resources.html?search=${encodeURIComponent(document.getElementById('searchInput').value.trim())}`; }); }
function render() { if (page === 'landing') return renderLanding(); if (page === 'login' || page === 'register') return renderAuth(page); if (!user) return; if (page === 'dashboard') { processUserNotifications(); return renderDashboard(); } if (page === 'tasks') return renderTasks(); if (page === 'notes') return renderNotes(); if (page === 'profile') return renderProfile(); if (page === 'tools') return renderTools(); if (page === 'resources') return renderResources(); if (['courses','exams','timetable'].includes(page)) return simplePageFor(page); const titles = { gpa:['GPA','Academic overview','Add course grades and calculate your weighted GPA.'], attendance:['Attendance','Track your presence','Keep a simple record of attended and missed sessions.'], expenses:['Expenses','Spend with context','Track everyday student expenses locally.'], 'study-planner':['Study planner','Make time visible','Plan focused study sessions around your real week.'] }; const info = titles[page] || titles.gpa; document.getElementById('app').innerHTML = shell(`${pageHeader('Build → review', info[1], info[2])}<div class="card p-5">${emptyState('bi-stars','Start with your own data','This page is ready for your first record. Existing data remains isolated to your account.')}</div>`); bindShell(); }
render();
setInterval(() => { if (protectedPages.includes(page) && currentUser()) { const before = JSON.stringify(getUserData()?.notifications || []); processUserNotifications(); const after = JSON.stringify(getUserData()?.notifications || []); if (before !== after && page === 'dashboard') render(); } }, 30000);
